insert into public.auction_lots(name,category,description,image_url,ends_at,starting_price,status) values
('Oscar Holm','Musiker','FIKTIV EKSEMPELPROFIL — ikke en bekræftet deltager. Fra scenen til centercourt. Oscar tager sin energi og spilleglæde med på banen — og du bliver hans makker. Glæd dig til en oplevelse med højt humør og plads til både gode dueller og skæve slag.','https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=1000&q=85','2027-03-31 18:00:00+02',500,'draft'),
('Alma Vester','Padelspiller','FIKTIV EKSEMPELPROFIL — ikke en bekræftet deltager. En makker med overblik, overskud og et skarpt netspil. Alma hjælper dig ind i kampen, så I sammen kan spille for mere lykke. Her er fællesskabet mindst lige så vigtigt som resultatet.','https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=1000&q=85','2027-03-31 18:00:00+02',500,'draft'),
('Emil Lund','Komiker','FIKTIV EKSEMPELPROFIL — ikke en bekræftet deltager. God timing er ikke kun noget, man bruger på en scene. Emil er klar på sjove dueller, et smil mellem boldene og en helt særlig dag som dit makkerpar.','https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=1000&q=85','2027-03-31 18:00:00+02',500,'draft'),
('Clara Storm','Musiker','FIKTIV EKSEMPELPROFIL — ikke en bekræftet deltager. Clara bytter mikrofonen ud med et padelbat for en dag. Byd på en plads ved hendes side og vær med til at give en god sag endnu mere medvind.','https://images.unsplash.com/photo-1524504388940-b1c1722653e1?auto=format&fit=crop&w=1000&q=85','2027-03-31 18:00:00+02',500,'draft'),
('August Friis','Sportsprofil','FIKTIV EKSEMPELPROFIL — ikke en bekræftet deltager. Konkurrencegen og fællesskab går hånd i hånd. August er klar til at spille sammen med dig og gøre hver eneste bold til en del af en større oplevelse.','https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=1000&q=85','2027-03-31 18:00:00+02',500,'draft'),
('Sofie Berg','Padelspiller','FIKTIV EKSEMPELPROFIL — ikke en bekræftet deltager. Sofie elsker spillets tempo og glæden ved at få sin makker til at lykkes. Kom med på banen til en dag med gode råd, stærke dueller og masser af spilleglæde.','https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=1000&q=85','2027-03-31 18:00:00+02',500,'draft');
